import java.util.Collections;
import java.util.HashMap;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;
public class PublishingVehicleTracker {
private final ConcurrentHashMap<String, SafePoint> locations;
private final Map<String, SafePoint> unmodifiableLocations;
public PublishingVehicleTracker(Map<String, SafePoint> initialLocations) {
this.locations = new ConcurrentHashMap<String, SafePoint>(initialLocations);
this.unmodifiableLocations = Collections.unmodifiableMap(this.locations);
}
public Map<String, SafePoint> getLocations() {
return unmodifiableLocations;
}
public SafePoint getLocation(String id) {
SafePoint point = locations.get(id);
if (point == null) {
throw new IllegalArgumentException("No vehicle found with id: " + id);
}
return point;
}
public void setLocation(String id, int x, int y) {
SafePoint point = locations.get(id);
if (point == null) {
throw new IllegalArgumentException("Cannot refresh non-existent vehicle with id: " + id);
}
point.set(x, y);
}
public static class SafePoint {
private int x;
private int y;
public SafePoint(int x, int y) {
this.x = x;
this.y = y;
}
public synchronized int getX() {
return x;
}
public synchronized int getY() {
return y;
}
public synchronized void set(int x, int y) {
this.x = x;
this.y = y;
}
@Override
public synchronized String toString() {
return "(" + x + ", " + y + ")";
}
}
public static void main(String[] args) throws InterruptedException {
Map<String, SafePoint> initial = new HashMap<String, SafePoint>();
initial.put("Vehicle1", new SafePoint(0, 0));
initial.put("Vehicle2", new SafePoint(5, 5));
final PublishingVehicleTracker tracker = new PublishingVehicleTracker(initial);
ExecutorService executor = Executors.newFixedThreadPool(2);
Runnable updateTask = new Runnable() {
@Override
public void run() {
tracker.setLocation("Vehicle1", 10, 15);
tracker.setLocation("Vehicle2", 20, 25);
System.out.println("Updated Vehicle1: " + tracker.getLocation("Vehicle1"));
System.out.println("Updated Vehicle2: " + tracker.getLocation("Vehicle2"));
}
};
Runnable readTask = new Runnable() {
@Override
public void run() {
System.out.println("Current locations map: " + tracker.getLocations());
try {
tracker.getLocation("Vehicle3");
} catch (IllegalArgumentException e) {
System.out.println("Expected exception: " + e.getMessage());
}
}
};
executor.execute(updateTask);
executor.execute(readTask);
executor.shutdown();
executor.awaitTermination(5, TimeUnit.SECONDS);
System.out.println("Final locations map: " + tracker.getLocations());
try {
tracker.setLocation("Vehicle4", 1, 1);
} catch (IllegalArgumentException e) {
System.out.println("Expected exception on update: " + e.getMessage());
}
}
}

