import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.List;
import java.util.concurrent.Callable;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.Future;
import java.util.concurrent.TimeUnit;
public class GrimoireInscriber {
enum Constellation {
ORION, LYRA, DRACO, PHOENIX
}
enum Resonance {
POSITIVE, NEGATIVE
}
static class Rune {
private final String name;
private final Constellation constellation;
private final Resonance resonance;
Rune(String name, Constellation constellation, Resonance resonance) {
this.name = name;
this.constellation = constellation;
this.resonance = resonance;
}
String getName() {
return name;
}
Constellation getConstellation() {
return constellation;
}
Resonance getResonance() {
return resonance;
}
@Override
public String toString() {
return name + "[" + constellation + "/" + resonance + "]";
}
}
static class Harmony {
private final Rune first;
private final Rune second;
Harmony(Rune first, Rune second) {
this.first = first;
this.second = second;
}
@Override
public String toString() {
return "Harmony(" + first.getName() + " <-> " + second.getName() + ")";
}
}
static class Grimoire {
private final List<Harmony> crystallizedHarmonies = new ArrayList<Harmony>();
synchronized void crystallize(Harmony harmony) {
crystallizedHarmonies.add(harmony);
}
synchronized List<Harmony> getCrystallizedHarmonies() {
return new ArrayList<Harmony>(crystallizedHarmonies);
}
synchronized int size() {
return crystallizedHarmonies.size();
}
}
static class RuneComparator implements Comparator<Rune> {
@Override
public int compare(Rune r1, Rune r2) {
int constellationCompare = r1.getConstellation().compareTo(r2.getConstellation());
if (constellationCompare != 0) {
return constellationCompare;
}
return r1.getResonance().compareTo(r2.getResonance());
}
}
public int channelTheGrimoire(List<Rune> candidateRunes, Grimoire grimoire) {
List<Rune> transmutedRunes = new ArrayList<Rune>(candidateRunes);
Collections.sort(transmutedRunes, new RuneComparator());
boolean[] used = new boolean[transmutedRunes.size()];
int harmonyCount = 0;
for (int i = 0; i < transmutedRunes.size(); i++) {
if (used[i]) {
continue;
}
Rune current = transmutedRunes.get(i);
for (int j = i + 1; j < transmutedRunes.size(); j++) {
if (used[j]) {
continue;
}
Rune candidate = transmutedRunes.get(j);
if (!candidate.getConstellation().equals(current.getConstellation())) {
break;
}
if (!candidate.getResonance().equals(current.getResonance())) {
used[i] = true;
used[j] = true;
Harmony harmony = new Harmony(current, candidate);
grimoire.crystallize(harmony);
harmonyCount++;
break;
}
}
}
return harmonyCount;
}
public static void main(String[] args) throws InterruptedException {
final GrimoireInscriber inscriber = new GrimoireInscriber();
final Grimoire sharedGrimoire = new Grimoire();
final List<Rune> batchOne = new ArrayList<Rune>();
batchOne.add(new Rune("Rune-A1", Constellation.ORION, Resonance.POSITIVE));
batchOne.add(new Rune("Rune-A2", Constellation.ORION, Resonance.NEGATIVE));
batchOne.add(new Rune("Rune-A3", Constellation.LYRA, Resonance.POSITIVE));
batchOne.add(new Rune("Rune-A4", Constellation.LYRA, Resonance.NEGATIVE));
batchOne.add(new Rune("Rune-A5", Constellation.DRACO, Resonance.POSITIVE));
final List<Rune> batchTwo = new ArrayList<Rune>();
batchTwo.add(new Rune("Rune-B1", Constellation.PHOENIX, Resonance.POSITIVE));
batchTwo.add(new Rune("Rune-B2", Constellation.PHOENIX, Resonance.NEGATIVE));
batchTwo.add(new Rune("Rune-B3", Constellation.DRACO, Resonance.NEGATIVE));
batchTwo.add(new Rune("Rune-B4", Constellation.ORION, Resonance.POSITIVE));
batchTwo.add(new Rune("Rune-B5", Constellation.ORION, Resonance.NEGATIVE));
ExecutorService executor = Executors.newFixedThreadPool(2);
Callable<Integer> taskOne = new Callable<Integer>() {
@Override
public Integer call() {
int count = inscriber.channelTheGrimoire(batchOne, sharedGrimoire);
System.out.println("Batch one harmonies formed: " + count);
return count;
}
};
Callable<Integer> taskTwo = new Callable<Integer>() {
@Override
public Integer call() {
int count = inscriber.channelTheGrimoire(batchTwo, sharedGrimoire);
System.out.println("Batch two harmonies formed: " + count);
return count;
}
};
Future<Integer> futureOne = executor.submit(taskOne);
Future<Integer> futureTwo = executor.submit(taskTwo);
int totalHarmonies = 0;
try {
totalHarmonies += futureOne.get();
totalHarmonies += futureTwo.get();
} catch (Exception e) {
Thread.currentThread().interrupt();
System.out.println("Error while channeling the grimoire: " + e.getMessage());
}
executor.shutdown();
executor.awaitTermination(5, TimeUnit.SECONDS);
System.out.println("Total harmonies formed: " + totalHarmonies);
System.out.println("Crystallized harmonies in grimoire: " + sharedGrimoire.size());
for (Harmony harmony : sharedGrimoire.getCrystallizedHarmonies()) {
System.out.println(harmony);
}
}
}

