import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;
final class Glyph {
public final int spark;
public final int glimmer;
Glyph(int spark, int glimmer) {
this.spark = spark;
this.glimmer = glimmer;
}
@Override
public String toString() {
return "Glyph[spark=" + spark + ", glimmer=" + glimmer + "]";
}
}
final class MysticBeastTracker {
private final ConcurrentHashMap<String, Glyph> perches;
MysticBeastTracker(Map<String, Glyph> initialPerches) {
this.perches = new ConcurrentHashMap<String, Glyph>(initialPerches);
}
Map<String, Glyph> getPerches() {
return Collections.unmodifiableMap(perches);
}
Glyph getPerch(String sigil) {
return perches.get(sigil);
}
void setPerch(String sigil, int spark, int glimmer) {
if (!perches.containsKey(sigil)) {
throw new IllegalArgumentException("No beast found with sigil: " + sigil);
}
perches.put(sigil, new Glyph(spark, glimmer));
}
Map<String, Glyph> getPerchesAsStatic() {
return Collections.unmodifiableMap(new HashMap<String, Glyph>(perches));
}
}
public class DreamscapeOrchestrator {
public static void main(String[] args) throws Exception {
Map<String, Glyph> initialPerches = new HashMap<String, Glyph>();
initialPerches.put("Phoenix", new Glyph(1, 10));
initialPerches.put("Griffin", new Glyph(2, 20));
initialPerches.put("Wyvern", new Glyph(3, 30));
initialPerches.put("Roc", new Glyph(4, 40));
initialPerches.put("Pegasus", new Glyph(5, 50));
final MysticBeastTracker tracker = new MysticBeastTracker(initialPerches);
ExecutorService executorService = Executors.newFixedThreadPool(5);
try {
executorService.submit(new Runnable() {
@Override
public void run() {
tracker.setPerch("Phoenix", 100, 200);
}
});
executorService.submit(new Runnable() {
@Override
public void run() {
tracker.setPerch("Griffin", 300, 400);
}
});
executorService.submit(new Runnable() {
@Override
public void run() {
tracker.setPerch("Wyvern", 500, 600);
}
});
executorService.submit(new Runnable() {
@Override
public void run() {
tracker.setPerch("Roc", 700, 800);
}
});
executorService.submit(new Runnable() {
@Override
public void run() {
tracker.setPerch("Pegasus", 900, 1000);
}
});
} finally {
executorService.shutdown();
executorService.awaitTermination(5, TimeUnit.SECONDS);
}
System.out.println("Current perches: " + tracker.getPerches());
System.out.println("Perch of Phoenix: " + tracker.getPerch("Phoenix"));
System.out.println("Perch of Unknown: " + tracker.getPerch("Unknown"));
Map<String, Glyph> snapshot = tracker.getPerchesAsStatic();
System.out.println("Snapshot of perches: " + snapshot);
try {
tracker.setPerch("Unknown", 1, 1);
} catch (IllegalArgumentException e) {
System.out.println("Caught expected exception: " + e.getMessage());
}
}
}

