import java.util.concurrent.Callable;
import java.util.concurrent.ExecutionException;
import java.util.concurrent.FutureTask;
interface Vision {
}
final class VisionCastException extends Exception {
VisionCastException(String message) {
super(message);
}
VisionCastException(String message, Throwable cause) {
super(message, cause);
}
}
final class SimpleVision implements Vision {
private final String description;
SimpleVision(String description) {
this.description = description;
}
@Override
public String toString() {
return "SimpleVision[" + description + "]";
}
}
abstract class DreamWeaver {
private final FutureTask<Vision> futureTask;
private final Thread pilotThread;
DreamWeaver() {
Callable<Vision> callable = new Callable<Vision>() {
@Override
public Vision call() throws VisionCastException {
return loadVision();
}
};
this.futureTask = new FutureTask<Vision>(callable);
this.pilotThread = new Thread(futureTask);
}
public abstract Vision loadVision() throws VisionCastException;
public void start() {
pilotThread.start();
}
public Vision get() throws VisionCastException {
try {
return futureTask.get();
} catch (InterruptedException e) {
Thread.currentThread().interrupt();
throw new VisionCastException("Vision summoning was interrupted", e);
} catch (ExecutionException e) {
Throwable cause = e.getCause();
if (cause instanceof VisionCastException) {
throw (VisionCastException) cause;
}
throw new VisionCastException("Unexpected error during vision summoning", cause);
}
}
}
public class DreamWeaverDemo {
public static void main(String[] args) {
DreamWeaver weaver = new DreamWeaver() {
@Override
public Vision loadVision() throws VisionCastException {
try {
Thread.sleep(500);
} catch (InterruptedException e) {
Thread.currentThread().interrupt();
throw new VisionCastException("Interrupted while summoning vision", e);
}
return new SimpleVision("A shimmering horizon of light");
}
};
weaver.start();
System.out.println("Vision summoning started, doing other work...");
try {
Vision vision = weaver.get();
System.out.println("Manifested vision: " + vision);
} catch (VisionCastException e) {
System.out.println("Failed to summon vision: " + e.getMessage());
}
DreamWeaver failingWeaver = new DreamWeaver() {
@Override
public Vision loadVision() throws VisionCastException {
throw new VisionCastException("The mists refused to part");
}
};
failingWeaver.start();
try {
Vision vision = failingWeaver.get();
System.out.println("Manifested vision: " + vision);
} catch (VisionCastException e) {
System.out.println("Failed to summon vision: " + e.getMessage());
}
}
}

