interface Charm<T> {
    T invoke();
}

interface RuneNode<T> {
    T compute();
    List<RuneNode<T>> getChildren();
}

final class StringCharm implements Charm<String> {
    private final String rawName;

    StringCharm(String rawName) {
        this.rawName = rawName;
    }

    @Override
    public String invoke() {
        return "Invoked[" + rawName + "]";
    }
}

final class SimpleRuneNode implements RuneNode<Integer> {
    private final int value;
    private final List<RuneNode<Integer>> children;

    SimpleRuneNode(int value) {
        this.value = value;
        this.children = new ArrayList<RuneNode<Integer>>();
    }

    void addChild(SimpleRuneNode child) {
        children.add(child);
    }

    @Override
    public Integer compute() {
        return value * value;
    }

    @Override
    public List<RuneNode<Integer>> getChildren() {
        return children;
    }
}

final class SpellcastingEngine<T> {
    List<T> castSequentially(List<Charm<T>> charms) {
        List<T> results = new ArrayList<T>();
        for (Charm<T> charm : charms) {
            results.add(charm.invoke());
        }
        return results;
    }

    List<T> castConcurrently(List<Charm<T>> charms, ExecutorService executor)
            throws InterruptedException, ExecutionException {
        List<Future<T>> futures = new ArrayList<Future<T>>();
        for (final Charm<T> charm : charms) {
            futures.add(executor.submit(new Callable<T>() {
                @Override
                public T call() {
                    return charm.invoke();
                }
            }));
        }
        List<T> results = new ArrayList<T>();
        for (Future<T> future : futures) {
            results.add(future.get());
        }
        return results;
    }

    List<T> traverseSequentially(RuneNode<T> root) {
        List<T> results = new ArrayList<T>();
        traverseSequentiallyHelper(root, results);
        return results;
    }

    private void traverseSequentiallyHelper(RuneNode<T> node, List<T> results) {
        results.add(node.compute());
        for (RuneNode<T> child : node.getChildren()) {
            traverseSequentiallyHelper(child, results);
        }
    }

    List<T> traverseConcurrently(RuneNode<T> root, ExecutorService executor)
            throws InterruptedException, ExecutionException {
        final List<T> results = Collections.synchronizedList(new ArrayList<T>());
        results.add(root.compute());
        List<Future<?>> futures = new ArrayList<Future<?>>();
        for (final RuneNode<T> child : root.getChildren()) {
            futures.add(executor.submit(new Runnable() {
                @Override
                public void run() {
                    List<T> subtreeResults = traverseSequentially(child);
                    results.addAll(subtreeResults);
                }
            }));
        }
        for (Future<?> future : futures) {
            future.get();
        }
        return results;
    }
}

