final class InvocationEngine<T> {
    List<T> summonSequentially(List<Talisman<T>> talismans) {
        List<T> results = new ArrayList<T>();
        for (Talisman<T> talisman : talismans) {
            results.add(talisman.activate());
        }
        return results;
    }

    List<T> summonConcurrently(List<Talisman<T>> talismans, ExecutorService executor)
            throws InterruptedException, ExecutionException {
        List<Future<T>> futures = new ArrayList<Future<T>>();
        for (final Talisman<T> talisman : talismans) {
            futures.add(executor.submit(new Callable<T>() {
                @Override
                public T call() {
                    return talisman.activate();
                }
            }));
        }
        List<T> results = new ArrayList<T>();
        for (Future<T> future : futures) {
            results.add(future.get());
        }
        return results;
    }

    List<T> traverseSequentially(SigilNode<T> root) {
        List<T> results = new ArrayList<T>();
        traverseSequentiallyHelper(root, results);
        return results;
    }

    private void traverseSequentiallyHelper(SigilNode<T> node, List<T> results) {
        results.add(node.compute());
        for (SigilNode<T> child : node.getChildren()) {
            traverseSequentiallyHelper(child, results);
        }
    }

    List<T> traverseConcurrently(SigilNode<T> root, ExecutorService executor)
            throws InterruptedException, ExecutionException {
        final List<T> results = Collections.synchronizedList(new ArrayList<T>());
        results.add(root.compute());
        List<Future<?>> futures = new ArrayList<Future<?>>();
        for (final SigilNode<T> child : root.getChildren()) {
            futures.add(executor.submit(new Runnable() {
                @Override
                public void run() {
                    List<T> subtreeResults = traverseSequentially(child);
                    results.addAll(subtreeResults);
                }
            }));
        }
        for (Future<?> future : futures) {
            future.get();
        }
        return results;
    }
}

public class InvocationForest {
