        ExecutorService executor = Executors.newFixedThreadPool(2);
        try {
            InvocationEngine<String> talismanEngine = new InvocationEngine<String>();
            List<Talisman<String>> talismans = new ArrayList<Talisman<String>>();
            talismans.add(new StringTalisman("Emberglyph"));
            talismans.add(new StringTalisman("Frostmark"));
            talismans.add(new StringTalisman("Stormsigil"));
            talismans.add(new StringTalisman("Shadowtoken"));

            List<String> sequentialResults = talismanEngine.summonSequentially(talismans);
            System.out.println("Sequential summoning results: " + sequentialResults);

            List<String> concurrentResults = talismanEngine.summonConcurrently(talismans, executor);
            System.out.println("Concurrent invocation results: " + concurrentResults);

            InvocationEngine<Integer> forestEngine = new InvocationEngine<Integer>();
            SimpleSigilNode root = new SimpleSigilNode(2);
            SimpleSigilNode childA = new SimpleSigilNode(3);
            SimpleSigilNode childB = new SimpleSigilNode(4);
            SimpleSigilNode grandchildA = new SimpleSigilNode(5);
            SimpleSigilNode grandchildB = new SimpleSigilNode(6);
