            root.addChild(childB);
            childA.addChild(grandchildA);
            childB.addChild(grandchildB);

            List<Integer> sequentialForestResults = forestEngine.traverseSequentially(root);
            System.out.println("Sequential sigil-forest results: " + sequentialForestResults);

