        Runnable sorcererConsumer = () -> {
            for (int i = 1; i <= 10; i++) {
                try {
                    vault.take();
                    Thread.sleep(70);
                } catch (InterruptedException e) {
                    Thread.currentThread().interrupt();
                }
            }
