        executor.submit(sorcererConsumer);

        executor.shutdown();
        executor.awaitTermination(30, TimeUnit.SECONDS);

        System.out.println("Vault isEmpty: " + vault.isEmpty());
        System.out.println("Vault isFull: " + vault.isFull());
    }
}

