import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;

public class MysticCounterSystem {

    static class MysticCounter {
        private int essence;

        MysticCounter(int initialEssence) {
            this.essence = initialEssence;
        }

        synchronized int get() {
            return essence;
        }

        synchronized int compareAndSwap(int expectedEssence, int newEssence) {
            int oldEssence = essence;
            if (oldEssence == expectedEssence) {
                essence = newEssence;
            }
            return oldEssence;
        }

        synchronized boolean compareAndSet(int expectedEssence, int newEssence) {
            return compareAndSwap(expectedEssence, newEssence) == expectedEssence;
        }
    }

    public static void main(String[] args) throws InterruptedException {
        MysticCounter counter = new MysticCounter(0);

        ExecutorService executor = Executors.newFixedThreadPool(1);

        Runnable spellcaster = () -> {
            for (int i = 0; i < 10; i++) {
                int current = counter.get();
                boolean success = counter.compareAndSet(current, current + 1);
                System.out.println(Thread.currentThread().getName() + " attempted transform from " + current
                        + " to " + (current + 1) + " - success: " + success);
            }
        };

        executor.submit(spellcaster);

        for (int i = 0; i < 10; i++) {
            int current = counter.get();
            boolean success = counter.compareAndSet(current, current + 1);
            System.out.println(Thread.currentThread().getName() + " attempted transform from " + current
                    + " to " + (current + 1) + " - success: " + success);
        }

        executor.shutdown();
        executor.awaitTermination(30, TimeUnit.SECONDS);

        System.out.println("Final essence: " + counter.get());
    }
}

