public class EagerSingletonRelicSystem {

    static class Relic {
        private static final Relic INSTANCE = new Relic();

        private Relic() {
            System.out.println("The relic is conjured at class loading");
        }

        static Relic getInstance() {
            return INSTANCE;
        }

        void invokeSpell() {
            System.out.println(Thread.currentThread().getName() + " invokes the relic's spell: 'Lumis Arcanum!'");
        }
    }

    public static void main(String[] args) throws InterruptedException {
        ExecutorService executor = Executors.newFixedThreadPool(3);

        Runnable summoner = () -> {
            Relic relic = Relic.getInstance();
            relic.invokeSpell();
        };

        executor.submit(summoner);
        executor.submit(summoner);
        executor.submit(summoner);

        executor.shutdown();
        executor.awaitTermination(30, TimeUnit.SECONDS);

        System.out.println("Ritual complete: all threads have invoked the relic's spell.");
    }
}

