import java.util.Set;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;

public class ChronomanticDragonTrackerSystem {

    static class MutableOrb {
        private int shimmerX;
        private int shimmerY;

        MutableOrb(int shimmerX, int shimmerY) {
            this.shimmerX = shimmerX;
            this.shimmerY = shimmerY;
        }

        MutableOrb(MutableOrb other) {
            this.shimmerX = other.shimmerX;
            this.shimmerY = other.shimmerY;
        }

        int getShimmerX() {
            return shimmerX;
        }

        void setShimmerX(int shimmerX) {
            this.shimmerX = shimmerX;
        }

        int getShimmerY() {
            return shimmerY;
        }

        void setShimmerY(int shimmerY) {
            this.shimmerY = shimmerY;
        }

        @Override
        public String toString() {
            return "MutableOrb(" + shimmerX + ", " + shimmerY + ")";
        }
    }

    static class Constellation<K, V> {
        private final Map<K, V> stars;

        Constellation() {
            this.stars = new HashMap<>();
        }

        Constellation(Map<K, V> initialStars) {
            this.stars = new HashMap<>(initialStars);
        }

        void put(K key, V value) {
            stars.put(key, value);
        }

        V get(K key) {
            return stars.get(key);
        }

        boolean containsKey(K key) {
            return stars.containsKey(key);
        }

        Set<K> keySet() {
            return stars.keySet();
        }

        Map<K, V> asMap() {
            return stars;
        }

        int size() {
            return stars.size();
        }
    }

    static class ChronomanticDragonTracker {
        private Constellation<String, MutableOrb> constellation;

        ChronomanticDragonTracker(Constellation<String, MutableOrb> initialConstellation) {
            this.constellation = deepClone(initialConstellation);
        }

        private static Constellation<String, MutableOrb> deepClone(Constellation<String, MutableOrb> source) {
            Constellation<String, MutableOrb> clone = new Constellation<>();
            for (Map.Entry<String, MutableOrb> entry : source.asMap().entrySet()) {
                clone.put(entry.getKey(), new MutableOrb(entry.getValue()));
            }
            return clone;
        }

        synchronized Constellation<String, MutableOrb> getConstellations() {
            Constellation<String, MutableOrb> clone = deepClone(constellation);
            Map<String, MutableOrb> unmodifiableMap = Collections.unmodifiableMap(clone.asMap());
            Constellation<String, MutableOrb> result = new Constellation<>(unmodifiableMap);
            return result;
        }

        synchronized MutableOrb getOrb(String sigil) {
            MutableOrb orb = constellation.get(sigil);
            if (orb == null) {
                return null;
            }
            return new MutableOrb(orb);
        }

        synchronized void setOrb(String sigil, int shimmerX, int shimmerY) {
            if (!constellation.containsKey(sigil)) {
                throw new IllegalArgumentException("Sigil not present in constellation: " + sigil);
            }
            MutableOrb orb = constellation.get(sigil);
            orb.setShimmerX(shimmerX);
            orb.setShimmerY(shimmerY);
        }
    }

    public static void main(String[] args) throws InterruptedException {
        Constellation<String, MutableOrb> initial = new Constellation<>();
        initial.put("Fafnir", new MutableOrb(10, 20));
        initial.put("Smaug", new MutableOrb(30, 40));
        initial.put("Draco", new MutableOrb(50, 60));

        ChronomanticDragonTracker tracker = new ChronomanticDragonTracker(initial);

        ExecutorService executor = Executors.newFixedThreadPool(2);

        Runnable updaterOne = () -> {
            for (int i = 0; i < 5; i++) {
                tracker.setOrb("Fafnir", 10 + i, 20 + i);
                MutableOrb orb = tracker.getOrb("Fafnir");
                System.out.println(Thread.currentThread().getName() + " updated Fafnir to " + orb);
                try {
                    Thread.sleep(20);
                } catch (InterruptedException e) {
                    Thread.currentThread().interrupt();
                }
            }
        };

        Runnable updaterTwo = () -> {
            for (int i = 0; i < 5; i++) {
                tracker.setOrb("Smaug", 30 + i, 40 + i);
                MutableOrb orb = tracker.getOrb("Smaug");
                System.out.println(Thread.currentThread().getName() + " updated Smaug to " + orb);
                try {
                    Thread.sleep(25);
                } catch (InterruptedException e) {
                    Thread.currentThread().interrupt();
                }
            }
        };

        executor.submit(updaterOne);
        executor.submit(updaterTwo);

        executor.shutdown();
        executor.awaitTermination(30, TimeUnit.SECONDS);

        Constellation<String, MutableOrb> finalConstellation = tracker.getConstellations();
        for (String sigil : finalConstellation.keySet()) {
            System.out.println("Final position of " + sigil + ": " + finalConstellation.get(sigil));
        }

        try {
            tracker.setOrb("Unknown", 0, 0);
        } catch (IllegalArgumentException e) {
            System.out.println("Caught expected exception: " + e.getMessage());
        }
    }
}

