        private final Map<K, V> currents;

        BubbleMap() {
            this.currents = new HashMap<>();
        }

        BubbleMap(Map<K, V> initialCurrents) {
            this.currents = new HashMap<>(initialCurrents);
        }

        void put(K key, V value) {
