        }

        private static BubbleMap<String, MutableShell> deepReplicate(BubbleMap<String, MutableShell> source) {
            BubbleMap<String, MutableShell> replica = new BubbleMap<>();
            for (Map.Entry<String, MutableShell> entry : source.asMap().entrySet()) {
                replica.put(entry.getKey(), new MutableShell(entry.getValue()));
            }
            return replica;
