        FluxThread t2 = new FluxThread(orbs);
        t1.start();
        t2.start();
        try {
            t1.join();
            t2.join();
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }
        System.out.println("Done");
    }

    static class Orb {
        private int mana;
        Orb(int mana) { this.mana = mana; }
        synchronized int getMana() { return mana; }
        synchronized void setMana(int mana) { this.mana = mana; }
    }

    static class ManaShard {
        private final int amount;
        ManaShard(int amount) { this.amount = amount; }
        int getAmount() { return amount; }
    }

    static class InsufficientManaException extends Exception {
        InsufficientManaException(String msg) { super(msg); }
    }

    static class EtherealFlux {
        static void transferEnergy(Orb from, Orb to, ManaShard amount) throws InsufficientManaException {
            synchronized (from) {
                synchronized (to) {
                    if (from.getMana() < amount.getAmount()) {
                        throw new InsufficientManaException("Insufficient mana");
                    }
                    from.setMana(from.getMana() - amount.getAmount());
                    to.setMana(to.getMana() + amount.getAmount());
                }
            }
        }
    }

    static class FluxThread extends Thread {
        private final Orb[] orbs;
        private final Random random = new Random();

        FluxThread(Orb[] orbs) {
            this.orbs = orbs;
        }

        public void run() {
            for (int i = 0; i < 10; i++) {
                int fromIndex = random.nextInt(orbs.length);
                int toIndex = random.nextInt(orbs.length);
                if (fromIndex == toIndex) {
                    toIndex = (toIndex + 1) % orbs.length;
                }
                ManaShard shard = new ManaShard(random.nextInt(10) + 1);
                try {
                    EtherealFlux.transferEnergy(orbs[fromIndex], orbs[toIndex], shard);
                } catch (InsufficientManaException e) {
                }
            }
        }
    }
}

