public class ChronoCrystalBalancer {
    public static void main(String[] args) {
        Crystal[] crystals = new Crystal[5];
        for (int i = 0; i < crystals.length; i++) {
            crystals[i] = new Crystal(100);
        }
        ResonanceThread t1 = new ResonanceThread(crystals);
        ResonanceThread t2 = new ResonanceThread(crystals);
        t1.start();
        t2.start();
        try {
            t1.join();
            t2.join();
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }
        System.out.println("Done");
    }

    static class Crystal {
        private int resonance;
        Crystal(int resonance) { this.resonance = resonance; }
        synchronized int getResonance() { return resonance; }
        synchronized void setResonance(int resonance) { this.resonance = resonance; }
    }

    static class ChronoShard {
        private final int amount;
        ChronoShard(int amount) { this.amount = amount; }
        int getAmount() { return amount; }
    }

    static class InsufficientChronoException extends Exception {
        InsufficientChronoException(String msg) { super(msg); }
    }

    static class TemporalFlux {
        static void shiftResonance(Crystal from, Crystal to, ChronoShard amount) throws InsufficientChronoException {
            synchronized (from) {
                synchronized (to) {
                    if (from.getResonance() < amount.getAmount()) {
                        throw new InsufficientChronoException("Insufficient chrono");
                    }
                    from.setResonance(from.getResonance() - amount.getAmount());
                    to.setResonance(to.getResonance() + amount.getAmount());
                }
            }
        }
    }

    static class ResonanceThread extends Thread {
        private final Crystal[] crystals;
        private final Random random = new Random();

        ResonanceThread(Crystal[] crystals) {
            this.crystals = crystals;
        }

        public void run() {
            for (int i = 0; i < 10; i++) {
                int fromIndex = random.nextInt(crystals.length);
                int toIndex = random.nextInt(crystals.length);
                if (fromIndex == toIndex) {
                    toIndex = (toIndex + 1) % crystals.length;
                }
                ChronoShard shard = new ChronoShard(random.nextInt(10) + 1);
                try {
                    TemporalFlux.shiftResonance(crystals[fromIndex], crystals[toIndex], shard);
                } catch (InsufficientChronoException e) {
                }
            }
        }
    }
}

