import java.util.Random;

public class GoblinGoldShuffle {
    static final int POUCH_COUNT = 5;
    static final int THREAD_COUNT = 2;
    static final int ITERATIONS = 10;

    public static void main(String[] args) throws InterruptedException {
        GoblinPouch[] pouches = new GoblinPouch[POUCH_COUNT];
        for (int i = 0; i < POUCH_COUNT; i++) {
            pouches[i] = new GoblinPouch(i, 100);
        }

        TradeThread[] threads = new TradeThread[THREAD_COUNT];
        for (int i = 0; i < THREAD_COUNT; i++) {
            threads[i] = new TradeThread(pouches, ITERATIONS, i);
        }

        for (TradeThread thread : threads) {
            thread.start();
        }

        for (TradeThread thread : threads) {
            thread.join();
        }

        for (GoblinPouch pouch : pouches) {
            System.out.println(pouch);
        }
    }

    static class GoblinPouch {
        final int id;
        int goldValue;
        final Object lock = new Object();

        GoblinPouch(int id, int goldValue) {
            this.id = id;
            this.goldValue = goldValue;
        }

        @Override
        public String toString() {
            return "GoblinPouch{id=" + id + ", goldValue=" + goldValue + '}';
        }
    }

    static class GoldClump {
        final int amount;

        GoldClump(int amount) {
            this.amount = amount;
        }
    }

    static class InsufficientGoldException extends Exception {
        InsufficientGoldException(String message) {
            super(message);
        }
    }

    static class SneakyTrade {
        static void transferGold(GoblinPouch from, GoblinPouch to, GoldClump clump) throws InsufficientGoldException {
            GoblinPouch first = from.id < to.id ? from : to;
            GoblinPouch second = from.id < to.id ? to : from;
            synchronized (first.lock) {
                synchronized (second.lock) {
                    if (from.goldValue < clump.amount) {
                        throw new InsufficientGoldException(
                                "Pouch " + from.id + " lacks sufficient gold for transfer of " + clump.amount);
                    }
                    from.goldValue -= clump.amount;
                    to.goldValue += clump.amount;
                }
            }
        }
    }

    static class TradeThread extends Thread {
        private final GoblinPouch[] pouches;
        private final int iterations;
        private final Random random;

        TradeThread(GoblinPouch[] pouches, int iterations, int seedOffset) {
            this.pouches = pouches;
            this.iterations = iterations;
            this.random = new Random(System.nanoTime() + seedOffset);
        }

        @Override
        public void run() {
            for (int i = 0; i < iterations; i++) {
                int fromIndex = random.nextInt(pouches.length);
                int toIndex = random.nextInt(pouches.length);
                if (fromIndex == toIndex) {
                    continue;
                }
                GoblinPouch from = pouches[fromIndex];
                GoblinPouch to = pouches[toIndex];
                GoldClump clump = new GoldClump(random.nextInt(20) + 1);
                try {
                    SneakyTrade.transferGold(from, to, clump);
                } catch (InsufficientGoldException e) {
                    // ignored
                }
            }
        }
    }
}

