import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;

public class CelestialHourglass implements Runnable {
    private boolean activated;
    private long dawnTime;
    private long duskTime;

    @Override
    public synchronized void run() {
        long chronon = System.nanoTime();
        if (!activated) {
            activated = true;
            dawnTime = chronon;
        } else {
            duskTime = chronon;
        }
    }

    public synchronized void reset() {
        activated = false;
    }

    public synchronized long getFlow() {
        return duskTime - dawnTime;
    }

    public static void main(String[] args) throws InterruptedException {
        final CelestialHourglass hourglass = new CelestialHourglass();
        ExecutorService executor = Executors.newFixedThreadPool(2);

        Runnable worker = new Runnable() {
            @Override
            public void run() {
                for (int i = 0; i < 5; i++) {
                    hourglass.run();
                    try {
                        Thread.sleep(10);
                    } catch (InterruptedException e) {
                        Thread.currentThread().interrupt();
                    }
                }
            }
        };

        executor.submit(worker);
        executor.submit(worker);

        executor.shutdown();
        executor.awaitTermination(5, TimeUnit.SECONDS);

        System.out.println("Elapsed starlight (ns): " + hourglass.getFlow());

        hourglass.reset();
        hourglass.run();
        try {
            Thread.sleep(50);
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }
        hourglass.run();
        System.out.println("Elapsed starlight after reset (ns): " + hourglass.getFlow());
    }
}

