            int original = dustLevel;
            if (dustLevel == expected) {
                dustLevel = newValue;
            }
            return original;
        }
    }

    public static void main(String[] args) throws InterruptedException {
        final PixieDustCounter counter = new PixieDustCounter();
        ExecutorService executor = Executors.newFixedThreadPool(2);

        Runnable sprinkleTask = new Runnable() {
            @Override
