                }
            }
        };

        executor.submit(sprinkleTask);
        executor.submit(sprinkleTask);

        executor.shutdown();
        executor.awaitTermination(5, TimeUnit.SECONDS);

        System.out.println("Final dust level: " + counter.getDustLevel());
    }
}

