import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;

public class MysticWatcher {
    private final ArcaneSource arcaneSource;

    private MysticWatcher(ArcaneSource arcaneSource) {
        this.arcaneSource = arcaneSource;
    }

    public static MysticWatcher summonInstance(ArcaneSource arcaneSource) {
        final MysticWatcher watcher = new MysticWatcher(arcaneSource);
        arcaneSource.addArcaneListener(new ArcaneListener() {
            @Override
            public void onMysticEvent(MysticEvent event) {
                watcher.castSpell(event);
            }
        });
        return watcher;
    }

    public void castSpell(MysticEvent event) {
        System.out.println("Spell cast in response to mystic event: " + event);
    }

    interface ArcaneSource {
        void addArcaneListener(ArcaneListener listener);
    }

    interface ArcaneListener {
        void onMysticEvent(MysticEvent event);
    }

    interface MysticEvent {
    }

    static class SimpleArcaneEvent implements MysticEvent {
        private final String description;

        SimpleArcaneEvent(String description) {
            this.description = description;
        }

        @Override
        public String toString() {
            return "SimpleArcaneEvent{description='" + description + "'}";
        }
    }

    static class SimpleArcaneSource implements ArcaneSource {
        private ArcaneListener listener;

        @Override
        public synchronized void addArcaneListener(ArcaneListener listener) {
            this.listener = listener;
        }

        synchronized void fireEvent(MysticEvent event) {
            if (listener != null) {
                listener.onMysticEvent(event);
            }
        }
    }

    public static void main(String[] args) throws InterruptedException {
        final SimpleArcaneSource source = new SimpleArcaneSource();
        MysticWatcher.summonInstance(source);

        ExecutorService executor = Executors.newFixedThreadPool(1);

        Runnable eventEmitter = new Runnable() {
            @Override
            public void run() {
                for (int i = 0; i < 3; i++) {
                    source.fireEvent(new SimpleArcaneEvent("Event #" + i));
                    try {
                        Thread.sleep(10);
                    } catch (InterruptedException e) {
                        Thread.currentThread().interrupt();
                    }
                }
            }
        };

        executor.submit(eventEmitter);

        executor.shutdown();
        executor.awaitTermination(5, TimeUnit.SECONDS);

        System.out.println("MysticWatcher demonstration complete.");
    }
}

